#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, Q;
    cin >> N >> Q;

    vector<bool> row_covered(N + 1, false), col_covered(N + 1, false);
    int rows_blocked = 0, cols_blocked = 0;
    long long black_remaining = (long long)(N - 2) * (N - 2);

    while (Q--) {
        int t, x;
        cin >> t >> x;
        if (t == 1) { // place white stone in column 1, row x
            if (!row_covered[x]) {
                row_covered[x] = true;
                // This row covers N-2 black stones minus those already blocked by columns
                black_remaining -= (N - 2 - cols_blocked);
                rows_blocked++;
            }
        } else { // t == 2, place white stone in row 1, column x
            if (!col_covered[x]) {
                col_covered[x] = true;
                // This column covers N-2 black stones minus those already blocked by rows
                black_remaining -= (N - 2 - rows_blocked);
                cols_blocked++;
            }
        }
    }

    cout << black_remaining << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, Q;
    cin >> N >> Q;

    // Initially black cells are the inner (N-2) x (N-2) area.
    long long black = 1LL * (N - 2) * (N - 2);

    // rowLim[r]: for row r, columns [2, rowLim[r]-1] may still be black.
    // colLim[c]: for column c, rows [2, colLim[c]-1] may still be black.
    vector<int> rowLim(N + 1, N);
    vector<int> colLim(N + 1, N);

    // DSU-like next pointers to skip already processed rows/columns.
    vector<int> nextRow(N + 1), nextCol(N + 1);
    for (int i = 0; i <= N; ++i) {
        nextRow[i] = i;
        nextCol[i] = i;
    }

    function<int(vector<int>&, int)> findp = [&](vector<int>& p, int x) -> int {
        if (p[x] == x) return x;
        return p[x] = findp(p, p[x]);
    };

    for (int qi = 0; qi < Q; ++qi) {
        int t, x;
        cin >> t >> x;

        if (t == 1) {
            // Place from first row into column x.
            int limit = colLim[x];
            black -= max(0, limit - 2);

            int r = findp(nextRow, 2);
            while (r < limit) {
                rowLim[r] = min(rowLim[r], x);
                nextRow[r] = findp(nextRow, r + 1);
                r = findp(nextRow, r);
            }
            colLim[x] = 2;
        } else {
            // Place from first column into row x.
            int limit = rowLim[x];
            black -= max(0, limit - 2);

            int c = findp(nextCol, 2);
            while (c < limit) {
                colLim[c] = min(colLim[c], x);
                nextCol[c] = findp(nextCol, c + 1);
                c = findp(nextCol, c);
            }
            rowLim[x] = 2;
        }
    }

    cout << black << '\n';
    return 0;
}

