int main() {
    int N, Q;
    scanf("%d %d", &N, &Q);

    bool row_white[N+1];
    bool col_white[N+1];
    for (int i = 0; i <= N; i++) {
        row_white[i] = false;
        col_white[i] = false;
    }

    long long rows_used = 0, cols_used = 0;

    for (int i = 0; i < Q; i++) {
        int t, x;
        scanf("%d %d", &t, &x);
        if (t == 1) {
            // place white in column 1, row x
            if (!row_white[x]) {
                row_white[x] = true;
                rows_used++;
            }
        } else {
            // place white in row 1, column x
            if (!col_white[x]) {
                col_white[x] = true;
                cols_used++;
            }
        }
    }

    long long total_black = (long long)(N-2) * (N-2);
    long long removed = rows_used * (N-2) + cols_used * (N-2) - rows_used * cols_used;
    long long remaining = total_black - removed;

    printf("%lld\n", remaining);

    return 0;
}

