#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

typedef struct {
    int n;
    int *bit;
} Fenwick;

void bit_add(Fenwick *fw, int idx, int val) {
    while (idx <= fw->n) {
        fw->bit[idx] += val;
        idx += idx & -idx;
    }
}

int bit_sum(Fenwick *fw, int idx) {
    int s = 0;
    while (idx > 0) {
        s += fw->bit[idx];
        idx -= idx & -idx;
    }
    return s;
}

int bit_kth(Fenwick *fw, int k) {
    int idx = 0;
    int pw = 1;
    while ((pw << 1) <= fw->n) pw <<= 1;
    for (int d = pw; d > 0; d >>= 1) {
        int nxt = idx + d;
        if (nxt <= fw->n && fw->bit[nxt] < k) {
            idx = nxt;
            k -= fw->bit[nxt];
        }
    }
    return idx + 1;
}

int main(void) {
    int N, Q;
    if (scanf("%d %d", &N, &Q) != 2) return 0;

    ll ans = (ll)(N - 2) * (N - 2);

    int M = N - 2; /* indices 2..N-1 mapped to 1..M */

    Fenwick rows, cols;
    rows.n = M;
    cols.n = M;
    rows.bit = (int *)calloc(M + 1, sizeof(int));
    cols.bit = (int *)calloc(M + 1, sizeof(int));

    for (int i = 1; i <= M; i++) {
        bit_add(&rows, i, 1);
        bit_add(&cols, i, 1);
    }

    int *rowLim = (int *)malloc((M + 1) * sizeof(int));
    int *colLim = (int *)malloc((M + 1) * sizeof(int));
    for (int i = 1; i <= M; i++) {
        rowLim[i] = N - 1;
        colLim[i] = N - 1;
    }

    int minRow = N - 1;
    int minCol = N - 1;

    for (int qi = 0; qi < Q; qi++) {
        int t, x;
        scanf("%d %d", &t, &x);

        if (x == N) continue; /* border already white, no effect */

        if (t == 1) {
            /* place in row 1, column x: whiten down to current minRow */
            if (x < minCol) {
                ans -= (ll)(minRow - 1);
                int k = bit_sum(&cols, x - 2 + 1) - bit_sum(&cols, x - 2);
                (void)k;
                minCol = x;
            } else {
                ans -= (ll)(colLim[x - 1] - 1);
            }

            int pos = x - 1; /* mapped */
            if (pos >= 1 && pos <= M && colLim[pos] == N - 1) {
                /* remove this column from unprocessed set if first time */
            }

            /* all still-unfixed columns >= x should already have their limit <= minRow,
               but only this queried column needs to remember the row limit */
            if (pos >= 1 && pos <= M) {
                if (colLim[pos] == N - 1) {
                    bit_add(&cols, pos, -1);
                }
                if (colLim[pos] > minRow) colLim[pos] = minRow;
            }

            /* when x creates new minCol, all untouched columns in [x..] conceptually get limit=minRow,
               but we only need queried columns' values later. */
        } else {
            /* place in column 1, row x: whiten right to current minCol */
            if (x < minRow) {
                ans -= (ll)(minCol - 1);
                minRow = x;
            } else {
                ans -= (ll)(rowLim[x - 1] - 1);
            }

            int pos = x - 1;
            if (pos >= 1 && pos <= M) {
                if (rowLim[pos] == N - 1) {
                    bit_add(&rows, pos, -1);
                }
                if (rowLim[pos] > minCol) rowLim[pos] = minCol;
            }
        }

        /* propagate new global minima to future first-time accesses via lazy idea:
           if a row/col is queried first time after minima decreased, its effective limit
           should be current minCol/minRow, not N-1. So store that on first access only. */
        if (t == 1) {
            int pos = x - 1;
            if (pos >= 1 && pos <= M && colLim[pos] == N - 1) colLim[pos] = minRow;
        } else {
            int pos = x - 1;
            if (pos >= 1 && pos <= M && rowLim[pos] == N - 1) rowLim[pos] = minCol;
        }
    }

    printf("%lld\n", ans);

    free(rows.bit);
    free(cols.bit);
    free(rowLim);
    free(colLim);
    return 0;
}

