        Arrays.fill(minColWhite, N);

        int rowLimit = N;
        int colLimit = N;

        for (int i = 0; i < Q; i++) {
            st = new StringTokenizer(br.readLine());
            int t = Integer.parseInt(st.nextToken());
            int x = Integer.parseInt(st.nextToken());

            if (t == 1) {
                if (x < colLimit) {
                    for (int r = colLimit - 1; r >= x; r--) {
                        blackCount -= (minRowWhite[r] - 2);
                    }
                    colLimit = x;
                }
            } else {
                if (x < rowLimit) {
                    for (int c = rowLimit - 1; c >= x; c--) {
                        blackCount -= (minColWhite[c] - 2);
                    }
                    rowLimit = x;
                }
            }
        }

        System.out.println(blackCount);
    }
}

import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        int Q = Integer.parseInt(st.nextToken());
        int[] top = new int[N]; // top[c] = how far down white has gone in col c
        int[] left = new int[N]; // left[r] = how far right white has gone in row r
        // top[c] starts at 0 (row 0 is empty/white boundary), left[r] starts at 0
        // Black stones at (r,c) 1<=r,c<=N-2, need r>top[c] and c>left[r]
        // bottom row N-1 and right col N-1 are white, so top[c]<=N-2 effectively stops at N-1
        Arrays.fill(top, 0);
        Arrays.fill(left, 0);
        // Use TreeMap for efficient updates
        // For column query c: advance top[c] while top[c]+1 <= N-2 and left[top[c]+1] >= c
        // For row query r: advance left[r] while left[r]+1 <= N-2 and top[left[r]+1] >= r
        StringBuilder sb = new StringBuilder();
        for (int q = 0; q < Q; q++) {
            st = new StringTokenizer(br.readLine());
            int type = Integer.parseInt(st.nextToken());
            int idx = Integer.parseInt(st.nextToken());
            if (type == 1) { // place in row 0, col idx -> propagate down col idx
                int c = idx;
                while (top[c] < N-1 && left[top[c]+1] >= c) top[c]++;
            } else { // place in col 0, row idx -> propagate right row idx
                int r = idx;
                while (left[r] < N-1 && top[left[r]+1] >= r) left[r]++;
            }
        }
        long black = 0;
        for (int c = 1; c <= N-2; c++) {
            // rows r: top[c] < r <= N-2 and left[r] < c
            // Need count of r in (top[c], N-2] with left[r] < c
            for (int r = top[c]+1; r <= N-2; r++) {
                if (left[r] < c) black++;
            }
        }
        System.out.println(black);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // Fast scanner
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N = fs.nextInt();
        int Q = fs.nextInt();

        // Initially black stones are in (N-2) x (N-2)
        long black = 1L * (N - 2) * (N - 2);

        // rowLimit[c]: smallest row index blocked in column c for type 1 queries
        // colLimit[r]: smallest column index blocked in row r for type 2 queries
        int[] rowLimit = new int[N + 1];
        int[] colLimit = new int[N + 1];
        Arrays.fill(rowLimit, N - 1);
        Arrays.fill(colLimit, N - 1);

        TreeSet<Integer> activeCols = new TreeSet<>();
        TreeSet<Integer> activeRows = new TreeSet<>();
        for (int i = 2; i <= N - 1; i++) {
            activeCols.add(i);
            activeRows.add(i);
        }

        for (int qi = 0; qi < Q; qi++) {
            int type = fs.nextInt();
            int x = fs.nextInt();

            if (type == 1) {
                // Place from top in column x
                int limit = rowLimit[x];
                black -= (long)(limit - 2);

                // For rows [2, limit-1], their reachable column limit may shrink to x
                while (true) {
                    Integer r = activeRows.ceiling(2);
                    if (r == null || r >= limit) break;
                    colLimit[r] = x;
                    activeRows.remove(r);
                }
            } else {
                // Place from left in row x
                int limit = colLimit[x];
                black -= (long)(limit - 2);

                // For cols [2, limit-1], their reachable row limit may shrink to x
                while (true) {
                    Integer c = activeCols.ceiling(2);
                    if (c == null || c >= limit) break;
                    rowLimit[c] = x;
                    activeCols.remove(c);
                }
            }
        }

        System.out.println(black);
    }
}
